'use strict';
const $=id=>document.getElementById(id), E=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])), shuffle=a=>[...a].sort(()=>Math.random()-.5);
const parts=[
{title:'Welcome & interact',sub:'Identify a visitor, understand their needs, respond politely and clarify.',goal:'Welcome → identify → ask → reformulate → offer help → close',vocab:[['How may I help you?','Comment puis-je vous aider ?','An open and professional greeting','How may I help you today?'],['on behalf of','au nom de','Representing another person or group','I am calling on behalf of the volleyball club.'],['registration','inscription','Signing up for an activity','I would like to ask about registration.'],['available','disponible','Possible or free','Are places still available?'],['membership','adhésion','Belonging to a club','The annual membership includes training.'],['confirm','confirmer','Check that information is correct','Let me confirm your request.'],['Could you spell…?','Pourriez-vous épeler… ?','Ask for the letters in a name','Could you spell your surname, please?'],['I will get back to you','Je reviendrai vers vous','Promise a follow-up','I will get back to you tomorrow.']],phrases:[['Open the conversation','Hello, this is Françoise speaking. How may I help you?','Use a calm opening and pause for the answer.'],['Identify the person','May I have your name and the name of your organisation, please?','Ask one question at a time.'],['Clarify','Could you tell me a little more about what you need?','Invite the other person to explain.'],['Reformulate','If I understand correctly, you would like to register a new player. Is that right?','Show you understood before responding.'],['Offer the next step','Of course. I can send you the details by email.','Give a helpful and realistic solution.'],['Close','Thank you for calling. Have a lovely day.','Professional and warm.']],scenarios:[
{t:'A parent calls about a new player',role:'A parent wants to enrol a teenager in the volleyball club.',exam:'Hello, I would like to register my daughter for volleyball, but I do not know how it works. Can you help?',ask:['Greet the parent and ask for their name.','Ask the player’s age and whether they have played before.','Reformulate the request and explain how you will send the information.'],a:'Hello, this is Françoise speaking. Of course I can help. May I have your name, please? How old is your daughter? Has she played volleyball before? So, you would like information about registration for a new player. I can send you the details by email.',b:'Good morning, this is Françoise from the volleyball association. I would be happy to help you with your daughter’s registration. Could you tell me how old she is and whether she has any previous experience? If I understand correctly, you would like to know the enrolment procedure. I will check the appropriate group and email you the next steps.',hint:'Welcome → age → previous experience → restate → next step.'},
{t:'A visiting team asks for information',role:'A visiting coach calls before a friendly match.',exam:'We are travelling to your club next Saturday. Could you tell me where we should go?',ask:['Identify the coach and team.','Ask about arrival time.','Confirm the need and offer to send the address.'],a:'Hello, thank you for calling. Which team are you from? What time do you plan to arrive? Would you like me to send you the address and directions to the sports hall?',b:'Welcome, this is Françoise speaking. May I have your name and the name of your team? Could you also confirm your expected arrival time? Just to make sure I have understood, you would like directions to the sports hall. I will send you the address and practical information.',hint:'Ask who is calling, when they arrive and what they need.'},
{t:'A volunteer offers to help',role:'Someone is interested in volunteering at an association event.',exam:'I saw your announcement for volunteers. I am interested, but I only have a few hours free.',ask:['Thank the person.','Ask about availability and preferred tasks.','Repeat their availability and offer a next step.'],a:'Thank you for your interest. What day and time are you available? What would you like to help with? So you are free for a few hours. I can send you the details.',b:'Thank you very much for offering to support our association. Could you tell me which time slots would suit you best and whether you would prefer welcoming visitors or helping with organisation? If I understand correctly, your availability is limited, so I will suggest a short shift.',hint:'Thank → when → type of task → confirm → follow-up.'},
{t:'A partner requests a meeting',role:'A local partner wants to discuss supporting a volleyball event.',exam:'Hello, I am calling about your next volleyball event. Could we arrange a short meeting?',ask:['Ask for the caller’s organisation.','Clarify their proposal and preferred date.','Confirm and promise a follow-up.'],a:'Thank you for calling. Which organisation are you from? What would you like to discuss? When are you available? I will check and get back to you.',b:'Thank you for your interest in our event. May I ask which organisation you represent and what kind of partnership you have in mind? Could you suggest two convenient times? If I understand correctly, you would like an introductory meeting. I will confirm our availability by email.',hint:'Organisation → purpose → dates → confirm.'}]},
{title:'Collect & transcribe',sub:'Understand messages, extract important details and write a concise note.',goal:'Listen / read → identify who, what, when, where → clarify → record essential facts',vocab:[['venue','lieu','Place where an event happens','The venue is the municipal sports hall.'],['postpone','reporter','Move an event to a later time','We need to postpone the meeting.'],['available slot','créneau disponible','Time that is free','Is there an available slot on Thursday?'],['attendee','participant','Someone attending an event','We expect twenty attendees.'],['contact details','coordonnées','Email address or phone number','Please leave your contact details.'],['deadline','date limite','Last date something can be done','The deadline is Friday.'],['instead of','au lieu de','Replacement choice','Thursday instead of Tuesday.'],['note down','noter','Write key facts','Let me note down the details.']],phrases:[['Ask to repeat','Could you repeat the date, please?','Do not guess information.'],['Check spelling','Could you spell the venue name, please?','Names and locations are important.'],['Confirm information','Let me check: Thursday the 12th at 6 p.m.','Repeat dates and times.'],['Transcribe briefly','The coach asks to move the training session to Thursday.','Write an accurate summary, not a transcript.'],['Finish','I have noted your request and will pass it on.','Make the next action explicit.']],scenarios:[
{t:'Training session rescheduled',role:'A coach leaves a message about changing a session.',exam:'Hello, this is Alex from the volleyball team. We need to move the training session from Tuesday at 6 p.m. to Thursday at 7 p.m. Please tell the players.',ask:['Identify the caller.','Say which date or time is changing.','Write a clear message for the players.'],a:'Alex called. Training is now on Thursday at 7 p.m. instead of Tuesday at 6 p.m. Please inform the players.',b:'Message from Alex, volleyball coach: the session previously scheduled for Tuesday at 6 p.m. has been moved to Thursday at 7 p.m. Please notify the players of this change.',hint:'Who? What changed? Old time? New time? Action?'},
{t:'A parent leaves a phone message',role:'A parent asks about a trial session.',exam:'My name is Emma Martin. My son would like to try volleyball this Wednesday. Please call me back on 06 24 15 38 70.',ask:['Identify the person and the request.','Note the day.','Write the callback information correctly.'],a:'Emma Martin called. Her son wants a trial session on Wednesday. Please call her back: 06 24 15 38 70.',b:'Callback request: Emma Martin would like to arrange a volleyball trial session for her son this Wednesday. Her contact number is 06 24 15 38 70. Please confirm availability.',hint:'Write the contact, purpose, day and follow-up.'},
{t:'Sports hall change',role:'The venue manager sends a change of location.',exam:'The main sports hall is unavailable on Friday. Please use the smaller hall next to the swimming pool. The entrance opens at 5:30 p.m.',ask:['Identify the problem.','Record the new venue and opening time.','Write a notice to participants.'],a:'The main sports hall is not available on Friday. Please use the smaller hall next to the swimming pool. Doors open at 5:30 p.m.',b:'Important venue update for Friday: due to the unavailability of the main sports hall, all participants should go to the smaller hall next to the swimming pool. Access starts at 5:30 p.m.',hint:'When? Why? Where? What time?'},
{t:'Partner meeting information',role:'A partner shares details of a short meeting.',exam:'We can meet on Monday at 10:15 a.m. at the community centre. Please bring the event schedule and an estimate of the number of volunteers.',ask:['Identify the meeting date, time and place.','List the two requested documents / details.','Write a short reminder.'],a:'Meeting on Monday at 10:15 a.m. at the community centre. Bring the event schedule and the estimated number of volunteers.',b:'Meeting reminder: please attend the partner meeting at the community centre on Monday at 10:15 a.m. Bring the event programme and an estimate of volunteer staffing needs.',hint:'Date → time → place → two things to bring.'}]},
{title:'Pass on instructions',sub:'Explain practical steps clearly and accurately on behalf of the association.',goal:'State the purpose → sequence instructions → give important constraints → check understanding',vocab:[['first / then / finally','d’abord / puis / enfin','Sequencing instructions','First, sign in. Then collect your badge.'],['check in','se présenter à l’accueil','Register on arrival','Please check in at the entrance.'],['set up','installer','Prepare equipment or a room','We need to set up the tables.'],['equipment','matériel','Items needed to do a task','Bring your sports equipment.'],['make sure','assurez-vous de','Emphasise an important action','Make sure the doors are locked.'],['in charge of','responsable de','Responsible for a task','The coordinator is in charge of the volunteers.'],['in case of','en cas de','Describes what to do if something happens','In case of a problem, contact the organiser.'],['safety rules','consignes de sécurité','Guidelines to avoid harm','Please follow the safety rules.']],phrases:[['Introduce a procedure','Here is what you need to do.','Use simple, direct sentences.'],['Step 1','First, please check in at reception.','Start with the action.'],['Step 2','Then, collect your badge and go to the sports hall.','Put the steps in chronological order.'],['Important condition','Make sure you arrive fifteen minutes early.','Draw attention to essential information.'],['Confirm','Is everything clear? Do you have any questions?','Check understanding.']],scenarios:[
{t:'Welcome a new volunteer on event day',role:'Explain the arrival procedure to a volunteer.',exam:'I am volunteering at the tournament. Where should I go, and what should I do first?',ask:['Explain where to report.','Give the steps in order.','Check understanding.'],a:'First, go to reception. Then, sign in and collect your badge. Finally, go to the sports hall and speak to the coordinator. Is that clear?',b:'Thank you for helping us today. When you arrive, please report to reception and sign the volunteer list. Next, collect your identification badge and go to the main sports hall, where the coordinator will assign your tasks. Do you have any questions?',hint:'First → then → finally → check.'},
{t:'Instructions to set up a volleyball event',role:'Guide a colleague who is preparing the venue.',exam:'Could you explain what I should prepare before the teams arrive?',ask:['Explain the main setup steps.','Mention safety.','Say who to contact if there is a problem.'],a:'First, set up the welcome desk. Then check the tables, signs and equipment. Make sure the exits are clear. If there is a problem, call the organiser.',b:'Before the teams arrive, please prepare the welcome area, display the directions and check that the equipment is ready. Make sure emergency exits remain accessible. If anything is missing or unsafe, inform the event coordinator immediately.',hint:'Setup → checks → safety → contact.'},
{t:'Explain registration instructions',role:'A new participant needs guidance on joining the club.',exam:'I have received the registration form. What should I do next?',ask:['Tell them which information to complete.','Explain how to return the form.','Tell them how confirmation works.'],a:'Please complete the form with your contact details. Then send it back to the club. We will check it and confirm your registration.',b:'First, fill in the required personal and contact details on the registration form. Next, return the completed form using the method indicated in the instructions. Once it has been checked, the club will contact you to confirm the next step.',hint:'Complete → return → confirmation. Avoid inventing fees or official requirements.'},
{t:'Explain a last-minute venue change',role:'Give directions to teams after a room change.',exam:'We have arrived, but the main hall is closed. What should we do?',ask:['Acknowledge the problem.','Explain an alternative route.','Confirm the person can find it.'],a:'I am sorry about the change. Please go to the smaller hall next to the swimming pool. Follow the signs and check in at the entrance. Can you find it?',b:'I apologise for the inconvenience. The match is taking place in the smaller hall beside the swimming pool. Please follow the temporary signs and report to the welcome desk there. Would you like me to repeat the directions?',hint:'Apology → new place → route → check understanding.'}]},
{title:'Read, use & explain information',sub:'Extract facts from a short professional document and give a reasoned response.',goal:'Read evidence → identify essential facts → summarise → recommend / justify',vocab:[['according to','selon','Refers to the information source','According to the schedule, doors open at 9.'],['because / therefore','parce que / donc','Explain cause and result','The hall is full; therefore we need another room.'],['however','cependant','Introduce a contrast','The event is popular; however, we need more volunteers.'],['I recommend','je recommande','Give a professional suggestion','I recommend sending a reminder.'],['capacity','capacité','Maximum number of people or places','The room has a limited capacity.'],['priority','priorité','What should be handled first','Safety is our priority.'],['support','soutenir','Help an organisation or project','The local business wants to support the event.'],['raise awareness','sensibiliser','Help people understand a cause','Our campaign raises awareness of the environment.']],phrases:[['Identify facts','According to the document, the event starts at 9 a.m.','Use information that is actually shown.'],['Summarise','The main point is that we need more volunteers.','Keep it concise.'],['Compare','Option A is easier; however, option B offers more space.','Contrast two choices.'],['Recommend','I recommend option B because it is more suitable.','State a reason, not just an opinion.'],['Explain your role','I work with several associations, including a volleyball association.','Do not claim that all association roles are paid.']],scenarios:[
{t:'Choose a volunteer shift',role:'Read the event coordinator’s message and recommend an action.',exam:'EVENT NOTE: Welcome desk: 9:00–12:00, two volunteers needed. Refreshment stand: 12:00–15:00, one volunteer needed. Setup: 8:00–9:00, three volunteers needed.',ask:['Say which role starts earliest.','Identify how many volunteers are needed for setup.','Recommend how to communicate the remaining needs.'],a:'Setup starts first at 8 a.m. It needs three volunteers. I recommend sending a message to ask for help.',b:'According to the event note, setup begins earliest, at 8 a.m., and requires three volunteers. I would recommend sharing the full shift schedule with members so that people can choose a suitable role.',hint:'Find the earliest time, the number and a practical suggestion.'},
{t:'Compare two meeting rooms',role:'A partner asks which room is more suitable.',exam:'ROOM A: 25 people; projector; available 2–4 p.m. ROOM B: 40 people; no projector; available 2–5 p.m. Meeting: 35 people, presentation needed.',ask:['Identify each room’s strengths and limitations.','Explain why neither is completely suitable.','Suggest a solution.'],a:'Room A has a projector, but it is too small. Room B is big enough, but it has no projector. We should ask for a projector in Room B.',b:'Room A provides presentation equipment but cannot accommodate the 35 participants. Room B has enough capacity, although it lacks a projector. I recommend booking Room B and arranging portable presentation equipment.',hint:'Capacity and projector are both essential.'},
{t:'Explain an environmental association notice',role:'You also help associations that protect local places and nature.',exam:'COMMUNITY NOTICE: Beach clean-up on Saturday from 10 a.m. to noon. Gloves and bags will be provided. Volunteers should bring water and suitable shoes. Meeting point: main beach entrance.',ask:['Summarise the activity and purpose.','Mention time, meeting point and equipment.','Explain why you think it is useful.'],a:'The association is organising a beach clean-up on Saturday from 10 to 12. Volunteers meet at the main entrance. Gloves and bags are provided. I think it is useful because it protects nature.',b:'The notice invites volunteers to a beach clean-up on Saturday between 10 a.m. and noon. Equipment will be provided, but participants should bring water and appropriate shoes. In my view, the event is valuable because it protects the local environment and encourages community involvement.',hint:'What / when / where / what to bring / why.'},
{t:'Review tournament attendance data',role:'Use a short report to suggest a practical improvement.',exam:'EVENT REPORT: 60 visitors expected; 85 arrived. Two volunteers worked at reception. Several visitors waited for information. Next event is in three weeks.',ask:['Compare expected and actual visitors.','Identify the problem.','Make a reasoned recommendation.'],a:'We expected 60 visitors, but 85 arrived. There was a queue at reception. I recommend having more volunteers next time.',b:'Attendance was higher than expected, with 85 visitors instead of 60. Since only two volunteers were assigned to reception, waiting times increased. I would recommend reinforcing the welcome desk and preparing clearer signs for the next event.',hint:'Facts → problem → recommendation and reason.'}]}];

// Expanded section-specific conversation bank and contextual vocabulary (2026 revision)
const vocabularyCategories = [{"Greetings & contact": [["This is Françoise speaking", "Françoise à l’appareil", "Introduce yourself on the phone", "Hello, this is Françoise speaking."], ["How may I help?", "Comment puis-je vous aider ?", "Ask what the person needs", "How may I help you today?"], ["I’m calling about…", "J’appelle au sujet de…", "Say why someone is calling", "I’m calling about Saturday’s match."], ["May I have your name?", "Puis-je avoir votre nom ?", "Ask who is calling", "May I have your name, please?"], ["on behalf of", "au nom de", "Representing a person or group", "I’m calling on behalf of the visiting team."], ["get back to you", "revenir vers vous", "Promise a later response", "I’ll check and get back to you."]], "Players & registrations": [["player", "joueur / joueuse", "Person participating in volleyball", "A new player would like to join."], ["parent / guardian", "parent / responsable légal", "Adult responsible for a young player", "A parent called about a trial session."], ["age group", "catégorie d’âge", "Players grouped by age", "Which age group is your daughter in?"], ["trial session", "séance d’essai", "First session to try an activity", "Is a trial session available?"], ["membership", "adhésion", "Belonging to the association", "Could you explain the membership process?"], ["registration form", "formulaire d’inscription", "Form to join the club", "Where can I find the registration form?"], ["renew a membership", "renouveler une adhésion", "Register again for a new period", "I’d like to renew my membership."]], "Training & matches": [["training session", "entraînement", "Regular practice", "What time is the training session?"], ["match / fixture", "match / rencontre prévue", "A competitive game", "When is the next match?"], ["tournament", "tournoi", "Event with several matches", "The tournament begins on Saturday."], ["coach", "entraîneur / entraîneuse", "Person who trains the team", "I’ll ask the coach for details."], ["team / opponent", "équipe / adversaire", "Group playing and its rival", "Which team are you playing against?"], ["warm-up", "échauffement", "Preparation before playing", "When does the warm-up begin?"], ["reschedule", "reprogrammer", "Change the time or date", "Can we reschedule the session?"]], "Places & practical help": [["sports hall / gym", "gymnase", "Indoor place for sports", "Which sports hall is the match in?"], ["main entrance", "entrée principale", "Main way into the building", "Please use the main entrance."], ["changing room", "vestiaire", "Room for changing clothes", "Where are the changing rooms?"], ["court", "terrain", "Area where volleyball is played", "Which court should the team use?"], ["directions", "itinéraire / indications", "How to reach somewhere", "Could you send me directions?"], ["parking area", "parking", "Place to park vehicles", "Is there parking near the sports hall?"]], "Volunteers & events": [["volunteer", "bénévole", "Someone helping at an event", "We need volunteers for the tournament."], ["shift / time slot", "créneau / permanence", "Period assigned to a task", "Which time slot suits you?"], ["welcome desk", "point d’accueil", "Place to welcome visitors", "Please report to the welcome desk."], ["organiser", "organisateur / organisatrice", "Person coordinating an event", "I will contact the organiser."], ["equipment", "matériel", "Tools and sports items", "Who is responsible for the equipment?"], ["availability", "disponibilités", "Times someone can help", "Could you tell me your availability?"]]}, {"Clarification & contact details": [["Could you repeat that?", "Pouvez-vous répéter ?", "Ask to hear something again", "Could you repeat the phone number?"], ["spell", "épeler", "Say the letters of a word", "Could you spell your surname?"], ["confirm", "confirmer", "Check a fact", "Can you confirm the date?"], ["contact number", "numéro de téléphone", "Telephone contact", "May I have a contact number?"], ["email address", "adresse e-mail", "Electronic contact", "Let me check your email address."], ["call back", "rappeler", "Return a call", "Could you call the parent back?"]], "Times, dates & changes": [["postpone", "reporter à plus tard", "Move an event to later", "We need to postpone the session."], ["bring forward", "avancer", "Move an event to earlier", "Can we bring the meeting forward?"], ["instead of", "au lieu de", "Indicate a replacement", "Thursday instead of Tuesday."], ["at 6:30 p.m.", "à 18 h 30", "Specific time in the evening", "The match starts at 6:30 p.m."], ["deadline", "date limite", "Last allowed date", "The deadline is Friday."], ["available slot", "créneau disponible", "Free period", "Is there an available slot on Wednesday?"]], "Match & venue updates": [["kick-off / start time", "heure de début", "When an event starts; use start time for volleyball", "Please confirm the match start time."], ["sports hall", "gymnase", "Indoor sports facility", "The sports hall has changed."], ["court number", "numéro de terrain", "Specific playing court", "The match is on court two."], ["visiting team", "équipe visiteuse", "Team coming from another club", "The visiting team is delayed."], ["cancelled", "annulé", "Not taking place", "Friday’s session has been cancelled."], ["replacement location", "lieu de remplacement", "Alternative place", "Please confirm the replacement location."]], "Notes & forwarding": [["take a message", "prendre un message", "Record information from a caller", "Can I take a message?"], ["note down", "noter", "Write the essential facts", "Let me note down the details."], ["pass on", "transmettre", "Give a message to another person", "I’ll pass the message on to the coach."], ["updated schedule", "planning mis à jour", "Revised timetable", "Please send the updated schedule."], ["follow-up", "suivi", "Action after a message", "A follow-up is needed."], ["action required", "action nécessaire", "What someone must do", "Action required: notify the players."]]}, {"Sequencing & checking": [["first / next / finally", "d’abord / ensuite / enfin", "Explain the steps in order", "First, sign in; next, collect your badge."], ["make sure", "assurez-vous de", "Emphasise an action", "Make sure the doors are clear."], ["check in", "se présenter / s’enregistrer", "Register on arrival", "Please check in at reception."], ["follow the signs", "suivre les panneaux", "Follow posted directions", "Please follow the signs to the court."], ["in charge of", "responsable de", "Responsible for an activity", "The coordinator is in charge of volunteers."], ["Is that clear?", "Est-ce clair ?", "Check understanding", "Is that clear, or should I repeat?"]], "Team & player instructions": [["arrive early", "arriver en avance", "Come before the start", "Please arrive early for the warm-up."], ["bring your kit", "apporter son équipement", "Come with sports clothes and items", "Please bring your sports kit."], ["warm up", "s’échauffer", "Prepare muscles for exercise", "The team should warm up before playing."], ["report an absence", "signaler une absence", "Tell the coach someone cannot attend", "Please report an absence to the coach."], ["check the timetable", "vérifier le planning", "Confirm session times", "Please check the updated timetable."], ["contact the coach", "contacter l’entraîneur", "Ask or inform the trainer", "Contact the coach if you are late."]], "Event setup & safety": [["set up", "installer", "Prepare an area", "Please set up the welcome desk."], ["put up signs", "installer des panneaux", "Display directional signs", "Put up signs near the entrance."], ["volunteer badge", "badge bénévole", "Identifier for helpers", "Please collect your volunteer badge."], ["emergency exit", "sortie de secours", "Exit used during emergencies", "Keep the emergency exit clear."], ["equipment check", "vérification du matériel", "Inspect items before use", "Do an equipment check before the match."], ["notify the organiser", "prévenir l’organisateur", "Alert responsible person", "Notify the organiser if anything is missing."]], "Changes & problems": [["alternative entrance", "autre entrée", "Different way in", "Please use the alternative entrance."], ["unavailable", "indisponible", "Not usable or free", "The main hall is unavailable."], ["delay", "retard", "Something starting late", "There is a delay of twenty minutes."], ["replacement court", "terrain de remplacement", "Different playing court", "Please move to the replacement court."], ["in case of", "en cas de", "Condition that triggers action", "In case of a problem, call the organiser."], ["apologise for the inconvenience", "présenter ses excuses pour le désagrément", "Polite way to acknowledge disruption", "We apologise for the inconvenience."]]}, {"Reading a notice": [["according to", "selon", "Cite a written source", "According to the notice, doors open at nine."], ["event programme", "programme de l’événement", "List of planned activities", "The event programme includes four matches."], ["capacity", "capacité d’accueil", "Number of people a room can hold", "The hall has a capacity of forty."], ["attendance", "fréquentation / présence", "Number of people present", "Attendance was higher than expected."], ["scheduled", "prévu / programmé", "Planned for a time", "The first match is scheduled for ten."], ["updated information", "informations actualisées", "More recent details", "Please check the updated information."]], "Comparing & interpreting": [["more than / fewer than", "plus que / moins que", "Compare quantities", "There were more visitors than expected."], ["whereas", "tandis que", "Contrast facts", "Room A has a projector, whereas Room B does not."], ["however", "cependant", "Show a limitation", "It is larger; however, it has no projector."], ["because / therefore", "parce que / par conséquent", "Explain reason and result", "We need more helpers because attendance has increased."], ["main issue", "principal problème", "Most important difficulty", "The main issue is the shortage of volunteers."], ["priority", "priorité", "Most urgent requirement", "Our priority is clear information."]], "Giving a recommendation": [["I suggest…", "je suggère…", "Offer an idea", "I suggest emailing the teams."], ["I recommend…", "je recommande…", "Make a professional recommendation", "I recommend adding another volunteer."], ["the best option", "la meilleure solution", "Compare possible choices", "The best option is Room B."], ["suitable", "adapté", "Appropriate for a purpose", "This room is more suitable."], ["raise awareness", "sensibiliser", "Increase public understanding", "The campaign aims to raise awareness."], ["community project", "projet associatif / local", "Activity serving the community", "This community project brings people together."]], "Association projects": [["association / non-profit", "association", "Organisation serving a purpose", "I also contribute to other associations."], ["local heritage", "patrimoine local", "History and cultural places", "The project protects local heritage."], ["environmental protection", "protection de l’environnement", "Taking care of nature", "The association supports environmental protection."], ["fundraising", "collecte de fonds", "Obtaining support for activities", "The event includes a fundraising activity."], ["support a cause", "soutenir une cause", "Help a social or environmental goal", "Volunteers help support a cause."], ["community involvement", "engagement local", "Participation by local people", "The event encourages community involvement."]]}];
const expandedPhraseBanks = [[["Open the conversation", ["Good morning, volleyball association. Françoise speaking. How can I help?", "Hello, you’re speaking to Françoise. What can I do for you today?", "Good afternoon. Thank you for calling the volleyball club. How may I help you?", "Hello, Françoise speaking. How can I assist you?"], "Sound welcoming; no need to memorise every option."], ["Identify the caller", ["May I have your name, please?", "Are you calling as a parent, a player or a coach?", "Could you tell me which team you represent?", "May I ask which organisation you are calling from?"], "Choose a question that fits the caller."], ["Clarify the request", ["Could you tell me a little more about the situation?", "Are you asking about training sessions or a match?", "Which age group are you interested in?", "Do you mean this Saturday or next Saturday?"], "Ask one clear question at a time."], ["Reformulate and confirm", ["So, you would like to register your daughter for next season. Is that right?", "If I understand correctly, the training time has changed.", "Let me make sure I understand: your team is arriving at half past nine.", "Just to confirm, you are looking for the entrance to the sports hall."], "Confirm the key facts instead of assuming."], ["Offer practical help", ["I can check the schedule and get back to you.", "I’ll ask the coach and let you know.", "I can email you the information about the sports hall.", "I can pass your message on to the person in charge."], "Never promise a time or decision you cannot confirm."], ["Close politely", ["Is there anything else I can help you with?", "Thank you for calling. Have a nice day.", "I’ll be in touch as soon as I have the information.", "We look forward to seeing you at the tournament."], "Finish with a realistic next step."]], [["Ask to repeat", ["Could you repeat the date, please?", "Sorry, I didn’t catch the time. Could you say it again?", "Could you speak a little more slowly, please?", "Was that Thursday or Tuesday?"], "Ask for only the missing detail."], ["Check spelling and numbers", ["Could you spell your surname, please?", "Could you spell the name of your club?", "Could you repeat the last four digits of your phone number?", "Is that fifteen or fifty?"], "Check names, contact details, dates and quantities."], ["Confirm the details", ["Let me read that back to you.", "So the match starts at ten thirty on Sunday, correct?", "Just to confirm, the new training time is seven p.m.", "Have I got your email address right?"], "Repeat important details exactly."], ["Record a concise message", ["Message from the coach: training has been moved to Thursday.", "The parent asked for a callback about a trial session.", "The visiting team expects to arrive at nine fifteen.", "The sports hall is unavailable on Friday; use the smaller hall."], "Write who / what / when / where / action."], ["Ask for missing information", ["What time should we expect you?", "Could I have a contact number, please?", "Which age category is the player in?", "Who should receive this message?"], "Collect only what is needed."], ["Close and follow up", ["Thank you. I’ve written that down.", "I’ll forward the information to the coach.", "I’ll send a confirmation once the schedule has been checked.", "I’ll make sure the relevant person receives your message."], "Do not invent that the change is confirmed."]], [["Introduce a procedure", ["Of course. Here’s what you need to do.", "I’ll explain the steps one by one.", "Let me walk you through the arrival procedure.", "There are three simple things to remember."], "Explain the purpose before giving steps."], ["Organise the steps", ["First, please report to the welcome desk.", "Next, sign the attendance sheet.", "Then, collect your badge from a volunteer.", "Finally, follow the signs to the sports hall."], "Use first / next / then / finally."], ["Give match and training instructions", ["Please arrive before the warm-up starts.", "Check the match schedule with your coach.", "Bring your sports kit and a water bottle.", "Please let us know if a player cannot attend."], "Only say what is supported by the situation."], ["Give setup and volunteer instructions", ["Please help set up the welcome table.", "Make sure the volleyball equipment is ready.", "Put the signs near the entrance.", "Ask the coordinator which task you should do next."], "Use short, concrete instructions."], ["Handle changes or problems", ["The main hall is closed, so please use the smaller sports hall.", "If the coach is delayed, contact the organiser.", "If you cannot find the entrance, call the welcome desk.", "Please wait for confirmation before changing the schedule."], "Problem → action → contact."], ["Check understanding and close", ["Does that make sense?", "Would you like me to repeat any of the steps?", "Do you have any questions before we begin?", "Let me know if you need any further help."], "Check comprehension without sounding impatient."]], [["Introduce the document", ["According to the programme, the first match starts at nine.", "The notice says the main hall is unavailable on Friday.", "The document gives the times and locations of the activities.", "I can see that three volunteers are needed for setup."], "Base every statement on the text."], ["Pick out important facts", ["The main point is the change of location.", "The event begins at ten and finishes at noon.", "The schedule shows two matches in the morning.", "The report says more visitors attended than expected."], "Give who / what / where / when."], ["Compare information", ["Room A is smaller than Room B.", "There are more visitors than expected.", "The morning shift starts earlier, whereas the afternoon shift ends later.", "The second option offers more space, but it has no projector."], "Compare facts, not guesses."], ["Explain consequences", ["Because the main hall is closed, the teams need directions.", "We have fewer volunteers than we need, so we should ask for help.", "This may cause a delay at reception.", "As a result, the organiser should send an update."], "Connect cause and result."], ["Recommend with reasons", ["I suggest sending a reminder to all participants.", "I would recommend the larger room because it has enough space.", "In my opinion, we should assign another volunteer to reception.", "The best option would be to confirm the change in writing."], "Recommendation + because + evidence."], ["Summarise and close", ["To sum up, the event is going ahead but in a different hall.", "The priority is to make sure everyone has the correct information.", "I would share the updated schedule with the teams.", "That is why I think this option is more practical."], "Finish with one actionable conclusion."]]];
const additionalMissions = [[["A coach asks about available training slots", "A coach calls to find an available time for an extra practice.", "Hello, our team would like an extra practice next week. Do you have an available training slot?", ["Greet and identify the coach.", "Ask the preferred day and time and age group.", "Confirm that you will check the schedule, without promising a free slot."], "Hello. Which team do you coach? What day and time would you prefer? I’ll check the training schedule and get back to you.", "Good afternoon, Françoise speaking. Could you tell me which age group this concerns and which days would suit you? I will check the sports hall timetable and confirm whether a slot is available.", "Team → age group → preferred times → check and reply."], ["A parent needs the right sports hall", "A parent cannot find where tonight’s practice is taking place.", "Hello, my son is supposed to train tonight, but I am not sure which gym to go to.", ["Ask which team and training session.", "Check the date and time.", "Offer the confirmed sports hall name, entrance or directions if known."], "Of course. Which team is your son in, and what time is the session? I’ll check which sports hall you need and send you the directions.", "I can help with that. Could you tell me your son’s age group and the scheduled start time? I’ll verify the correct sports hall and entrance, then share the directions so you can find it easily.", "Identify team → confirm session → check hall → send directions."], ["A player cannot attend a match", "A player wants to report an absence before Saturday’s match.", "Hi, I cannot play this Saturday because I am away. Who should I tell?", ["Acknowledge and ask which team.", "Confirm which match and date.", "Offer to pass the message to the coach."], "Thanks for letting us know. Which team do you play for? Is it this Saturday’s match? I’ll pass the message on to your coach.", "Thank you for notifying us in advance. Could you confirm your team and the match concerned? I’ll forward your absence to the coach so they can make the necessary arrangements.", "Thank → team → match → coach."], ["A tournament volunteer asks about a shift", "A volunteer wants to help but needs exact hours and duties.", "Hello, I can help on tournament day, but only in the morning. What could I do?", ["Thank the volunteer.", "Ask their available hours and preferred tasks.", "Offer to check which shift fits."], "Thank you! What time are you free in the morning? Would you like to help at reception or with setup? I’ll check the shifts.", "We appreciate your offer. Could you specify your morning availability and whether you prefer welcoming teams or helping to prepare the hall? I’ll match that with the event schedule and confirm a suitable role.", "Availability → task preferences → check shifts."]], [["Referee information needs to be relayed", "A caller leaves a change of match start time for the organiser.", "Hello, it’s Jordan from the visiting club. Our match on Sunday will now start at 11:30 instead of 10:45. Please notify your coach.", ["Confirm the team and match.", "Repeat old and new start times.", "Write a short message naming the action required."], "Jordan called. Sunday’s match will start at 11:30 instead of 10:45. Please tell the coach.", "Message from Jordan at the visiting club: Sunday’s match has been rescheduled from 10:45 a.m. to 11:30 a.m. Action: inform the coach and verify the updated schedule.", "Who → Sunday match → old time → new time → notify."], ["Volunteer changes availability", "A volunteer sends new time slots.", "Hello, I am no longer free from nine to noon on Saturday. I can help between one and four in the afternoon.", ["Identify who is speaking.", "Record the old and new shifts.", "Pass the update to the volunteer coordinator."], "The volunteer cannot come from nine to twelve on Saturday. They are available from one to four. Please inform the coordinator.", "Availability update for Saturday: the original 9 a.m.–noon shift is no longer possible. The volunteer is available from 1–4 p.m. Please check the new allocation with the coordinator.", "Write changed availability; avoid assuming acceptance."], ["A visiting club provides travel details", "The visiting coach shares arrival time and contact information.", "Our team will arrive around 9:20 on Saturday. We have twelve players. Please call our coach Sam on 06 31 42 58 79 if there is a delay.", ["Note day, time and number of players.", "Repeat the contact number to confirm.", "Record what to do if delayed."], "The visiting team arrives Saturday at about 9:20 with twelve players. The coach is Sam: 06 31 42 58 79. Call if delayed.", "Visiting team travel note: expected arrival Saturday at approximately 9:20 a.m.; twelve players. Delay contact: coach Sam, 06 31 42 58 79. Please confirm these details.", "When → how many → contact → action."], ["A sports hall reports a cancellation", "A local facilities contact reports a temporary closure.", "The sports hall is closed on Wednesday evening for maintenance. The volleyball club cannot use court one from six until eight.", ["Identify the day and affected location.", "Note the closure time and reason.", "Draft a factual message to the team without inventing another venue."], "The sports hall is closed Wednesday from 6 to 8 p.m. because of maintenance. Court one is unavailable. The team needs an update.", "Facilities notice: maintenance has closed court one on Wednesday between 6 and 8 p.m., so the club cannot hold its scheduled session there. Please notify the coach and confirm alternative arrangements.", "Place → time → reason → follow-up."]], [["Give visiting teams arrival instructions", "A visiting coach asks how to check in for a weekend tournament.", "We are coming to the tournament with our team. What should we do when we arrive?", ["Tell the team where to check in.", "Explain how to find the right court and organiser.", "Check their understanding."], "When you arrive, please go to the welcome desk. Then check the match programme and follow the signs to your court. Ask the organiser if you need help.", "On arrival, please report to the welcome desk so the organisers know you are here. You can then check the programme for your court and match time. Follow the signs and contact the coordinator if anything is unclear.", "Welcome → registration → schedule → court."], ["Explain what to do before a match", "A parent wants to know the practical steps before their child plays.", "My daughter is playing in the tournament tomorrow. What should she do when we get there?", ["Explain arrival and check-in.", "Mention coach, kit and warm-up.", "Avoid inventing an arrival deadline."], "Please arrive in time for the warm-up. Check the programme, find the coach and bring her sports kit and water.", "I recommend arriving early enough to locate the court and meet the coach before the warm-up. Please check the published timetable and make sure your daughter has her kit and water. The coach can confirm any team-specific instructions.", "Arrival → coach → equipment → warm-up."], ["Guide volunteers through registration desk setup", "A colleague is preparing the welcome area.", "I am helping with the reception table for the first time. Could you explain what I should prepare?", ["Explain what materials to prepare.", "Explain how to receive teams.", "Mention who handles unclear requests."], "First, set up the table and signs. Then prepare the lists and badges. When visitors arrive, ask for their team and direct them to the right court. Ask the coordinator if you are unsure.", "Start by arranging the welcome desk, clearly displayed signs and any available attendance lists. As teams arrive, confirm their names and give the appropriate directions. Refer unusual questions or missing information to the coordinator.", "Table → materials → welcome → escalation."], ["Explain a changed match location", "A player has been sent to the wrong court.", "The schedule says court one, but a volunteer told me to go to court three. What should I do?", ["Acknowledge confusion.", "Explain that the updated schedule must be checked first.", "Give an instruction after confirmation and check understanding."], "Sorry about the confusion. Please wait at reception while I check the updated court number. I’ll tell you where to go.", "I apologise for the mixed information. Let me verify the latest court allocation with the organiser before directing you. Once confirmed, I’ll explain exactly where to go and make sure the team has the update.", "Do not guess: verify → direct → confirm."]], [["Review a tournament notice", "Use a short tournament notice to guide visitors.", "NOTICE: Saturday tournament: doors open at 8:30 a.m.; first match 9:15 a.m.; teams must check in at reception. The refreshment stand opens at 10 a.m.", ["Identify opening and first-match times.", "Explain the first step for arriving teams.", "Suggest one useful reminder to send."], "Doors open at 8:30 and the first match is at 9:15. Teams should check in at reception. I suggest reminding everyone of these times.", "According to the notice, the venue opens at 8:30 a.m. and the opening match begins at 9:15 a.m. All teams must report to reception on arrival. I recommend emailing teams a concise arrival reminder in advance.", "Use exact times → required check-in → action."], ["Choose a volunteer plan", "Compare shifts and recommend priorities.", "SHIFT NOTE: Setup 8–9 a.m.: 3 required, 1 confirmed. Welcome desk 9 a.m.–noon: 2 required, 2 confirmed. Cleanup 5–6 p.m.: 4 required, 2 confirmed.", ["Identify which shifts lack volunteers.", "Calculate how many are missing for each.", "Recommend how to recruit replacements."], "Setup needs two more volunteers and cleanup needs two more. The welcome desk is fully covered. I suggest asking members to help with setup and cleanup.", "The schedule shows shortages in two shifts: setup requires two more volunteers, and cleanup also needs two additional people. Reception is fully staffed. I would prioritise a message requesting support specifically for the uncovered periods.", "Required − confirmed; prioritise gaps."], ["Read a sports hall availability notice", "Assess whether a room suits a proposed event.", "FACILITIES: Hall A: available Tuesday 6–8 p.m., one court. Hall B: available Wednesday 5–9 p.m., two courts. Proposed event: Wednesday 6–8 p.m. for two teams training at once.", ["Extract availability for each hall.", "Determine which hall matches day and number of courts.", "Justify your recommendation."], "Hall B is available on Wednesday and has two courts. I recommend Hall B because both teams can train at the same time.", "Hall A is only available on Tuesday and has one court, whereas Hall B is available on Wednesday and provides two courts. Since the session requires two simultaneous team practices on Wednesday, Hall B is the suitable choice.", "Day + time + two courts → choose."], ["Explain a local association notice", "Use an association notice from Françoise’s wider interests.", "NOTICE: Community heritage walk on Sunday at 10 a.m. Volunteers meet at the town hall at 9:30. The event is free; participants should wear comfortable shoes.", ["Explain what happens, when and where.", "Tell volunteers and participants what they need to know.", "Give a reason why the activity may benefit the community."], "The heritage walk starts Sunday at 10. Volunteers meet at the town hall at 9:30. Participants should wear comfortable shoes. It helps people discover local heritage.", "The notice advertises a free community heritage walk on Sunday at 10 a.m., with volunteers asked to meet at the town hall half an hour earlier. I think this helps residents discover and value their local heritage while bringing people together.", "Separate volunteer meeting time and event start."]]];
parts.forEach((part,i)=>{ part.phrases=expandedPhraseBanks[i]; part.scenarios.push(...additionalMissions[i].map(([t,role,exam,ask,a,b,hint])=>({t,role,exam,ask,a,b,hint}))); });

const quizzes=[
[{type:'single',q:'A caller says: “I would like to enrol my son.” What is the best first response?',options:['The match is cancelled.','Of course. May I ask how old he is?','You must send your payment today.'],answer:1,hint:'Ask for relevant information before inventing a procedure.'},{type:'fill',q:'Complete the clarification: “If I ______ correctly, you need information about registration.”',answer:'understand',hint:'This verb means comprendre.'},{type:'order',q:'Build a polite professional opening.',tokens:['How','may','I','help','you','today?'],hint:'Start with How.'},{type:'multi',q:'Select ALL suitable questions for a new caller.',options:['Could you tell me your name?','What is your password?','Which team are you calling from?','When would you like to visit?'],answer:[0,2,3],hint:'Choose relevant, polite questions; never request a password.'}],
[{type:'single',q:'The caller says: “Thursday, not Tuesday.” Which note is accurate?',options:['Move the session to Tuesday.','Cancel every session.','Change the session to Thursday.'],answer:2,hint:'The new day comes after “not”.'},{type:'fill',q:'Complete: “Could you ______ the phone number, please?”',answer:'repeat',hint:'Use this verb to ask for information again.'},{type:'order',q:'Build a clear follow-up sentence.',tokens:['I','will','pass','the','message','on.'],hint:'Subject + will + verb.'},{type:'multi',q:'For a changed meeting, which details matter?',options:['New time','Favourite colour','Meeting place','Contact person'],answer:[0,2,3],hint:'Choose details needed to act on the message.'}],
[{type:'single',q:'Which is a clear instruction?',options:['First, please sign in at reception.','Sometimes the table was nice.','I have visited a beach.'],answer:0,hint:'Look for a sequencing word and action.'},{type:'fill',q:'Complete: “Make ______ you arrive early.”',answer:'sure',hint:'A two-word expression meaning assurez-vous.'},{type:'order',q:'Build an instruction for a volunteer.',tokens:['Please','check','in','at','reception','first.'],hint:'Please + action + place + first.'},{type:'multi',q:'Which expressions help explain a procedure?',options:['First','Then','My favourite film','Finally'],answer:[0,1,3],hint:'Look for sequencing expressions.'}],
[{type:'single',q:'A room holds 25 people, but 35 will attend. What should you say?',options:['The room is large enough.','The room is too small for the group.','No one needs to attend.'],answer:1,hint:'Compare the capacity with attendance.'},{type:'fill',q:'Complete: “I recommend this option ______ it is safer.”',answer:'because',hint:'Introduce a reason.'},{type:'order',q:'Build a reasoned recommendation.',tokens:['I','recommend','Room','B','because','it','is','larger.'],hint:'Opinion + because + reason.'},{type:'multi',q:'Which elements create a useful document-based answer?',options:['A correct fact','A clear recommendation','A reason','Invented details'],answer:[0,1,2],hint:'Use evidence, advice and a reason; do not invent.'}]
];
const state={page:0,scenario:{},results:{},attempts:{},mockIndex:-1,mockAnswers:[],mockSeconds:420,mockRunning:false,done:false};let interval=null,recorder=null,recChunks=[],recordURL=null;
const sectionNames=['Orientation','1 · Welcome & interact','2 · Collect & transcribe','3 · Pass on instructions','4 · Read & explain','Timed mock','CFL trainer report'];
function save(){try{localStorage.setItem('francoise_lilate_final_v1',JSON.stringify({page:state.page,scenario:state.scenario,results:state.results,attempts:state.attempts,mockAnswers:state.mockAnswers}))}catch{}}
function load(){try{let v=JSON.parse(localStorage.getItem('francoise_lilate_final_v1')||'{}');Object.assign(state,{page:v.page??0,scenario:v.scenario||{},results:v.results||{},attempts:v.attempts||{},mockAnswers:v.mockAnswers||[]})}catch{}}
function nav(){ $('nav').innerHTML=sectionNames.map((t,i)=>`<button class="navbtn ${i===state.page?'active':''}" data-page="${i}"><span class="num">${i===0?'↗':i===5?'◷':i===6?'✓':i}</span><span>${E(t)}</span></button>`).join('') }
function go(i){if(state.mockRunning&& !confirm('Leave the mock? The timer will be stopped.'))return;stopTimer();stopRecorder();state.page=Math.max(0,Math.min(6,i));save();render();window.scrollTo({top:0,behavior:'smooth'})}
function render(){nav();$('stageNumber').textContent=String(state.page+1).padStart(2,'0')+' / 07';$('stageTitle').textContent=sectionNames[state.page];$('stageSubtitle').textContent=state.page>=1&&state.page<=4?parts[state.page-1].sub:state.page===0?'Review what you will do before starting.':state.page===5?'Independent practice with individual timed tasks.':'Copy or export your CFL / Digiforma lesson record.';$('progress').value=Math.round(state.page/6*100);$('progressLabel').textContent=Math.round(state.page/6*100)+'%';$('prev').disabled=state.page===0;$('next').disabled=state.page===6;$('next').textContent=state.page===4?'Open timed mock →':state.page===5?'CFL report →':'Next section →';$('content').innerHTML=state.page===0?intro():state.page<=4?guided(state.page-1):state.page===5?mock():report();if(state.page===5)attachMock();if(state.page===6)populateReport();}
function intro(){return `<div class="panel"><h3>How the LILATE IA assessment works</h3><p>For this IA format, the published practical guide describes a <b>maximum 30-minute, four-part assessment</b>. The competencies are: welcome and interact; collect and transcribe information; relay instructions/information; and consult, use and explain documents. Reading, listening, speaking and writing are assessed across tasks. The real platform may change the question type and time limit automatically.</p><div class="two">${parts.map((p,i)=>`<div class="mini"><b>Part ${i+1} · ${E(p.title)}</b><small>${E(p.sub)}</small></div>`).join('')}</div><p class="footnote">The self-introduction is a useful communication rehearsal, not a guaranteed standalone question. The simulated QCM, multi-select, fill-in and word-order items below are <b>training scaffolds</b>; the real assessment is not guaranteed to use these exact item types.</p></div><div class="panel"><h3>Understand common instructions</h3><div class="instructions">${[['Choose ONE answer','Select only one option. / Choisissez une seule réponse.'],['Choose ALL correct answers','More than one answer may be correct. / Plusieurs réponses possibles.'],['Complete the sentence','Write the missing word. / Complétez avec le mot manquant.'],['Put words in the correct order','Click tiles to build a sentence. / Remettez les mots dans l’ordre.'],['Listen and respond','Play the prompt, note the essential information, then reply. / Écoutez et répondez.'],['Read and explain','Use the facts in the text and justify your answer. / Lisez puis expliquez.'],['Record your response','Allow microphone access if you want a recording. / Autorisez le micro pour vous enregistrer.'],['Submit / Next','Confirm your answer and continue. / Validez, puis passez à la suite.']].map(x=>`<div class="mini"><b>${x[0]}</b><small>${x[1]}</small></div>`).join('')}</div></div><div class="panel"><h3>Personal introduction · useful opening practice</h3><p>You may need to identify yourself or explain your role in a professional interaction. Keep it short and accurate.</p><div class="phrase"><b>Level A2/B1</b>My name is Françoise. I work for a volleyball association. I also work with other associations. I help organise activities and communicate with people.</div><div class="phrase"><b>Level B1+/B2</b>My name is Françoise. My paid position is with a volleyball association, where I help with coordination and communication. I am also involved with other associations, including initiatives related to local communities and the environment. I enjoy making information clear and helping people work together.</div><p class="footnote">Adapt the wording to your exact responsibilities; do not state tasks you do not perform.</p><label for="selfintro"><b>Try your own 30–45 second introduction</b></label><textarea class="response" id="selfintro" placeholder="My name is…"></textarea>${recordControls('intro')}<div class="row"><button class="smallbtn" data-say="My name is Françoise. I work for a volleyball association. I also work with other associations. I help organise activities and communicate with people.">▶ Hear a model</button><button class="smallbtn" data-custom="intro">Save my introduction</button></div></div>`}
function guided(i){let p=parts[i],sel=state.scenario[i]??0,cats=Object.keys(vocabularyCategories[i]);return `<div class="panel"><span class="pill">GUIDED MODE</span><span class="pill alt">Trainer acts as examiner</span><h3>The response pathway</h3><div class="section-intro"><b>${E(p.goal)}</b><p>Choose the expression that feels natural to you. Each step offers several examples. Practice aloud, then choose an examiner mission and respond without reading the model.</p></div><div class="two">${p.phrases.map(x=>`<div class="phrase phrase-expanded"><b>${E(x[0])}</b><div class="phrase-examples">${x[1].map((sentence,k)=>`<div class="phrase-example"><span>${k+1}. ${E(sentence)}</span><button class="smallbtn" data-say="${E(sentence)}" title="Listen to this expression">▶ Listen</button></div>`).join('')}</div><span>${E(x[2])}</span></div>`).join('')}</div></div><div class="panel"><h3>Vocabulary by real-life situation</h3><p class="muted">Choose the topic you need. Each word includes a French translation, meaning, example and optional pronunciation. No artificial groups of four.</p><label for="vocabSelect"><b>Choose vocabulary topic</b></label><select class="inputline" id="vocabSelect"><option value="all">All vocabulary for this section (${cats.reduce((n,c)=>n+vocabularyCategories[i][c].length,0)} expressions)</option>${cats.map((name,j)=>`<option value="${j}">${E(name)} (${vocabularyCategories[i][name].length})</option>`).join('')}</select><div id="vocabGrid" class="vocab">${vocabHTML(i,'all')}</div></div><div class="panel"><h3>Interactive practice · recognise useful language</h3><p class="muted">The short exercises are unchanged. They provide immediate feedback but are not the priority for today’s oral role-play.</p>${quizzes[i].map((q,j)=>quizHTML(i,j,q)).join('')}</div><div class="panel"><h3>Live examiner missions</h3><p>Choose from ${p.scenarios.length} realistic examiner-style situations. Your trainer reads the caller’s prompt; respond step by step, ask a question, check details and propose a realistic next action. The models stay hidden until requested.</p><label for="scenarioSelect"><b>Choose a scenario</b></label><select class="inputline" id="scenarioSelect">${p.scenarios.map((s,j)=>`<option value="${j}" ${j===sel?'selected':''}>${j+1}. ${E(s.t)}</option>`).join('')}</select><div id="scenarioArea">${scenarioHTML(i,sel)}</div></div>`}
function vocabHTML(i,scope){let cats=Object.keys(vocabularyCategories[i]);return cats.map((name,k)=>({name,k,words:vocabularyCategories[i][name]})).filter(x=>scope==='all'||String(x.k)===String(scope)).map(({name,words})=>`<div class="vocab-category"><h4>${E(name)}</h4><div class="vocab">${words.map(v=>`<div class="word"><b>${E(v[0])}</b><em>${E(v[1])}</em><small>${E(v[2])}</small><p>${E(v[3])}</p><button class="smallbtn" data-say="${E(v[3])}">▶ Listen</button></div>`).join('')}</div></div>`).join('')}
function quizHTML(i,j,q){let id=`q${i}_${j}`,r=state.results[id];let base=`<div class="scenario"><div class="scenario-head"><h4>${j+1}. ${q.type==='single'?'Choose ONE answer':q.type==='multi'?'Choose ALL correct answers':q.type==='fill'?'Complete the sentence':'Put words in order'}</h4><span class="pill alt">Practice</span></div><p>${E(q.q)}</p>`;let rest='';if(q.type==='single'||q.type==='multi'){rest=`<div id="${id}choices">${q.options.map((v,k)=>`<button class="choice" data-choice="${id}" data-idx="${k}" data-multi="${q.type==='multi'?'1':'0'}">${String.fromCharCode(65+k)}. ${E(v)}</button>`).join('')}</div>${q.type==='multi'?`<button class="secondary" data-checkmulti="${id}">Check selected answers</button>`:''}`}else if(q.type==='fill'){rest=`<input class="inputline" id="${id}input" placeholder="Type the missing word" aria-label="Missing word"><button class="secondary" data-checkfill="${id}">Check answer</button>`}else{let words=shuffle(q.tokens.map((v,k)=>({v,k})));rest=`<div class="assembled" id="${id}selected" aria-label="Selected words"></div><div class="tokens" id="${id}tokens">${words.map(w=>`<button data-token="${id}" data-key="${w.k}">${E(w.v)}</button>`).join('')}</div><div class="row"><button class="secondary" data-checkorder="${id}">Check word order</button><button class="ghost" data-resetorder="${id}">Reset</button></div>`}return base+rest+`<div class="row" style="margin-top:12px"><button class="smallbtn" data-hint="${id}">💡 Hint</button><button class="smallbtn" data-answer="${id}">Show answer</button></div><div class="feedback ${r?.correct?'good':r?'bad':''}" id="${id}feed">${r? (r.correct?'✓ Correct':'✗ Try again') :''}</div><div id="${id}extra"></div></div>`}
function scenarioHTML(i,j){let s=parts[i].scenarios[j],id=`s${i}_${j}`;return `<div class="scenario selected"><div class="scenario-head"><h4>${E(s.t)}</h4><span class="pill">MISSION ${j+1}/${parts[i].scenarios.length}</span></div><p><b>Situation:</b> ${E(s.role)}</p><div class="prompt"><strong>EXAMINER SAYS</strong><p>${E(s.exam)}</p><button class="smallbtn" data-say="${E(s.exam)}">▶ Play examiner prompt</button><button class="smallbtn" data-transcript="${id}">Show / hide prompt text</button></div><div class="task"><b>Your task · respond in order</b><ol>${s.ask.map(x=>`<li>${E(x)}</li>`).join('')}</ol></div><label><b>Plan or write your response</b></label><textarea class="response" id="${id}response" placeholder="Start with a polite greeting. Ask questions, confirm the details, and propose a next step.">${E(state.results[id]?.text||'')}</textarea><div class="row"><button class="secondary" data-saveresponse="${id}">Save written response</button><button class="smallbtn" data-hintscenario="${id}">💡 Hint</button><button class="smallbtn" data-model="${id}">View A2/B1 and B1+/B2 models</button></div><div id="${id}support"></div>${recordControls(id)}<p class="footnote">Speaking and writing are assessed manually here. A computer cannot reliably grade your spoken answer. Ask your trainer to check clarity, accuracy and task completion.</p></div>`}
function recordControls(id){return `<div class="recordbox" data-record="${id}"><div class="row"><button class="secondary" data-recstart="${id}">● Start recording</button><button class="ghost" data-recstop="${id}" disabled>■ Stop</button><span id="${id}recstatus" class="muted">Optional microphone practice · no upload</span></div><div id="${id}recordout"></div></div>`}
function mock(){return `<div class="panel"><span class="pill alt">EXAM-LIKE · INDEPENDENT MODE</span><h3>Timed rehearsal · four professional missions</h3><p>One mission per LILATE competency area. Each mission has a <b>7-minute practice timer</b>; this is an approximate section allocation, not a claim that each official question lasts seven minutes. Hints and model answers are hidden until the end. The timer automatically moves to the next mission. You can record each spoken response if browser permissions allow it.</p><p class="footnote">Real LILATE IA questions may have individual countdowns and advance automatically. This page is an independent approximation, not an identical replica.</p><div class="row"><button class="primary" id="startMock">${state.mockIndex>=0?'Restart timed mock':'Start 28-minute mock'}</button><button class="ghost" id="endMock">End and review</button></div></div><div id="mockArea">${state.mockIndex>=0?mockTaskHTML():`<div class="panel"><p>Ready? You will receive a new professional situation from each section. Work without hints or models until the review.</p></div>`}</div><div id="mockReview">${state.done?reviewHTML():''}</div>`}
function mockTaskHTML(){let i=state.mockIndex;if(i<0||i>=4)return '';let j=state.mockAnswers[i]?.scenario??0,s=parts[i].scenarios[j];return `<div class="mockbar"><div><b>PART ${i+1} / 4</b><div>${E(parts[i].title)}</div></div><div><span class="timer" id="clock">${clock(state.mockSeconds)}</span><div class="footnote" style="color:#cce2eb">Time remaining in this practice part</div></div></div><div class="panel"><h3>${E(s.t)}</h3><div class="mockquestion"><strong>Situation</strong>${E(s.role)}<p><strong>Read or listen to the message</strong>${E(s.exam)}</p><button class="smallbtn" data-say="${E(s.exam)}">▶ Listen to message</button></div><div class="task"><b>Instructions: complete all the tasks</b><ol>${s.ask.map(x=>`<li>${E(x)}</li>`).join('')}</ol></div><label><b>Your response / essential notes</b></label><textarea class="response" id="mockResponse" placeholder="Respond in clear English. You may speak aloud and record yourself.">${E(state.mockAnswers[i]?.text||'')}</textarea>${recordControls('mock'+i)}<div class="row" style="margin-top:14px"><button class="primary" id="submitMock">Submit & next →</button><button class="ghost" id="pauseMock">${state.mockRunning?'Pause practice timer':'Resume practice timer'}</button></div></div>`}
function clock(s){return String(Math.floor(s/60)).padStart(2,'0')+':'+String(s%60).padStart(2,'0')}
function reviewHTML(){return `<div class="panel"><h3>Mock review · reflect and improve</h3><p class="score">Mock completed. Check each answer against two levels of model response. This is a training review, not an official LILATE score.</p>${state.mockAnswers.map((a,i)=>{let s=parts[i].scenarios[a.scenario];return `<div class="scenario"><h4>Part ${i+1} · ${E(s.t)}</h4><p><b>Your response:</b> ${E(a.text||'(No written notes submitted; spoken response may have been recorded separately.)')}</p><div class="model"><strong>A2/B1 model</strong>${E(s.a)}</div><div class="model"><strong>B1+/B2 model</strong>${E(s.b)}</div></div>`}).join('')}<button class="secondary" id="retryMock">Try another combination</button></div>`}
function report(){return `<div class="panel"><h3>CFL · session evaluation and reporting</h3><p>Editable fields with a copy-ready training-centre summary and CSV export. Record <b>actual</b> performance; guided quiz success alone is not evidence of oral proficiency.</p><div class="two skillfields"><div><label for="date">Lesson date</label><input id="date" type="date"><label for="duration">Duration in minutes</label><input id="duration" type="number" min="0" value="60"><label for="status">Session status</label><select id="status"><option>Réalisée</option><option>En cours</option><option>Reportée</option></select><label for="lessonurl">Lesson URL (optional)</label><input id="lessonurl" placeholder="https://..."></div><div><label for="oral">Speaking / interaction</label><select id="oral">${assessmentOptions()}</select><label for="listening">Listening comprehension</label><select id="listening">${assessmentOptions()}</select><label for="reading">Reading comprehension</label><select id="reading">${assessmentOptions()}</select><label for="writing">Writing / transcription</label><select id="writing">${assessmentOptions()}</select></div></div><div class="two skillfields"><div><label for="strengths">Achievements / learner strengths</label><textarea id="strengths" placeholder="Clearer greetings, reformulation, good time and date extraction…"></textarea></div><div><label for="targets">Areas to consolidate / next steps</label><textarea id="targets" placeholder="Practise clarifying questions, review connectors…"></textarea></div></div><div class="skillfields"><label for="trainer">Trainer observations</label><textarea id="trainer" placeholder="Notes from the live session; exam readiness and action points."></textarea></div><div class="row" style="margin-top:17px"><button class="primary" id="copyReport">Copy CFL summary</button><button class="secondary" id="csvReport">Download CSV</button><button class="ghost" id="jsonReport">Download JSON</button><button class="ghost" id="printReport">Print / PDF</button></div><div id="reportFeedback" class="feedback" aria-live="polite"></div></div><div class="panel"><h3>Practice performance snapshot</h3><div id="snapshot"></div><p class="footnote">Multiple choice, fill-in, word order and multi-select questions are formative activities. Oral expression, listening and document interpretation must be evaluated using the actual responses.</p></div>`}
function assessmentOptions(){return ['Non évalué','Non acquis','En cours d’acquisition','Acquis'].map(v=>`<option>${v}</option>`).join('')}
function populateReport(){$('date').value=new Date().toISOString().slice(0,10);$('snapshot').innerHTML=parts.map((p,i)=>{let total=quizzes[i].length,correct=quizzes[i].filter((q,j)=>state.results[`q${i}_${j}`]?.correct).length,role=parts[i].scenarios.filter((s,j)=>state.results[`s${i}_${j}`]?.text).length;return `<div class="mini" style="margin-bottom:8px"><b>${E(p.title)}</b><small>Guided knowledge checks: ${correct}/${total} correct · Scenario notes saved: ${role}/4</small></div>`}).join('')}
function quizById(id){let m=id.match(/^q(\d+)_(\d+)$/);return m?quizzes[+m[1]][+m[2]]:null}
function judge(id,correct){state.attempts[id]=(state.attempts[id]||0)+1;state.results[id]={correct,attempts:state.attempts[id]};let feed=$(id+'feed');if(feed){feed.textContent=correct?'✓ Correct — well done!':'✗ Not quite — try again or request a hint.';feed.className='feedback '+(correct?'good':'bad')}save()}
function showExtra(id,html){let el=$(id+'extra');if(el)el.innerHTML=html}
function answerText(q){return q.type==='single'?q.options[q.answer]:q.type==='multi'?q.answer.map(j=>q.options[j]).join(' / '):q.type==='fill'?q.answer:q.tokens.join(' ')}
function stopTimer(){if(interval){clearInterval(interval);interval=null}state.mockRunning=false}
function startTimer(){stopTimer();state.mockRunning=true;interval=setInterval(()=>{if(!state.mockRunning)return;state.mockSeconds--;let el=$('clock');if(el){el.textContent=clock(Math.max(0,state.mockSeconds));el.classList.toggle('warning',state.mockSeconds<60)}if(state.mockSeconds<=0)nextMock()},1000)}
function startMock(){stopTimer();stopRecorder();state.mockAnswers=parts.map((p,i)=>({scenario:Math.floor(Math.random()*p.scenarios.length),text:''}));state.mockIndex=0;state.mockSeconds=420;state.done=false;render();startTimer();save()}
function nextMock(){if(state.mockIndex<0)return;let el=$('mockResponse');if(el)state.mockAnswers[state.mockIndex].text=el.value;stopTimer();stopRecorder();if(state.mockIndex<3){state.mockIndex++;state.mockSeconds=420;render();startTimer()}else{state.mockIndex=-1;state.done=true;render()}save()}
function finishMock(){if(state.mockIndex>=0){let el=$('mockResponse');if(el)state.mockAnswers[state.mockIndex].text=el.value}stopTimer();stopRecorder();state.mockIndex=-1;state.done=true;render();save()}
function attachMock(){}
async function startRecorder(id){if(!navigator.mediaDevices?.getUserMedia||!window.MediaRecorder){alert('Recording is not available in this browser. Use HTTPS or localhost and allow the microphone, or practise aloud without recording.');return}stopRecorder();try{let stream=await navigator.mediaDevices.getUserMedia({audio:true});recChunks=[];let mime=['audio/webm;codecs=opus','audio/webm','audio/mp4'].find(m=>MediaRecorder.isTypeSupported(m))||'';recorder=new MediaRecorder(stream,mime?{mimeType:mime}:{});recorder.ondataavailable=e=>{if(e.data.size)recChunks.push(e.data)};recorder.onstop=()=>{stream.getTracks().forEach(t=>t.stop());let blob=new Blob(recChunks,{type:recorder.mimeType||'audio/webm'});if(recordURL)URL.revokeObjectURL(recordURL);recordURL=URL.createObjectURL(blob);let el=$(id+'recordout');if(el)el.innerHTML=`<audio controls src="${recordURL}"></audio> <a href="${recordURL}" download="Francoise_LILATE_${id}.${blob.type.includes('mp4')?'m4a':'webm'}">Download recording</a>`;let status=$(id+'recstatus');if(status)status.textContent='Recorded locally · download to keep';};recorder.start();let a=document.querySelector(`[data-recstart="${id}"]`),b=document.querySelector(`[data-recstop="${id}"]`);if(a)a.disabled=true;if(b)b.disabled=false;let s=$(id+'recstatus');if(s)s.textContent='● Recording…';}catch(err){alert('Microphone could not be started. Check browser permissions and HTTPS. '+err.message)}}
function stopRecorder(){if(recorder&&recorder.state==='recording'){recorder.stop()}document.querySelectorAll('[data-recstart]').forEach(x=>x.disabled=false);document.querySelectorAll('[data-recstop]').forEach(x=>x.disabled=true)}
function speak(s){if(!('speechSynthesis'in window)){alert('Speech playback is not available in this browser. Your trainer can read the prompt.');return}speechSynthesis.cancel();const u=new SpeechSynthesisUtterance(s);u.lang='en-GB';u.rate=.9;let vs=speechSynthesis.getVoices();let v=vs.find(v=>/^en-GB/i.test(v.lang)&&!/robot|compact/i.test(v.name))||vs.find(v=>/^en-US/i.test(v.lang));if(v)u.voice=v;speechSynthesis.speak(u)}
function reportData(){let f=id=>$(id).value;let checks=parts.map((p,i)=>({name:p.title,correct:quizzes[i].filter((q,j)=>state.results[`q${i}_${j}`]?.correct).length,total:quizzes[i].length}));return {learner:'Françoise',lesson:'LILATE IA final guided rehearsal + mock',date:f('date'),duration_minutes:f('duration'),status:f('status'),lesson_url:f('lessonurl'),skills:{speaking:f('oral'),listening:f('listening'),reading:f('reading'),writing:f('writing')},guided_checks:checks,scenario_notes_saved:parts.reduce((a,p,i)=>a+p.scenarios.filter((s,j)=>state.results[`s${i}_${j}`]?.text).length,0),mock_parts_completed:state.mockAnswers.filter(x=>x.text).length,strengths:f('strengths'),areas_to_consolidate:f('targets'),trainer_observations:f('trainer'),next_steps:f('targets')}}
function reportText(d){return ['CFL · COMPTE RENDU PÉDAGOGIQUE','Apprenante : '+d.learner,'Séance : '+d.lesson,'Date : '+d.date,'Durée : '+d.duration_minutes+' min','Statut : '+d.status,'Lien : '+d.lesson_url,'Contenus : Accueil et interaction ; recueil et transcription ; transmission de consignes ; exploitation de documents ; simulation chronométrée.','Types : compréhension orale/écrite, expression orale/écrite, QCM d’entraînement, réponses multiples, phrases à compléter, ordre des mots, jeux de rôle.',...d.guided_checks.map(c=>c.name+': '+c.correct+'/'+c.total+' réponses guidées correctes'),'Jeux de rôle préparés : '+d.scenario_notes_saved,'Compétences : expression orale '+d.skills.speaking+' ; compréhension orale '+d.skills.listening+' ; compréhension écrite '+d.skills.reading+' ; expression écrite '+d.skills.writing,'Acquis / points forts : '+d.strengths,'En cours / à renforcer : '+d.areas_to_consolidate,'Observations : '+d.trainer_observations,'Suite / objectifs : '+d.next_steps].join('\n')}
function download(filename,content,type){let blob=new Blob([content],{type});let a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=filename;document.body.appendChild(a);a.click();setTimeout(()=>URL.revokeObjectURL(a.href),2000);a.remove()}
function csvCell(s){return '"'+String(s??'').replace(/"/g,'""')+'"'}
function exportCSV(){let d=reportData(),heads=['Learner','Lesson','Date','Duration (min)','Status','Content','Exercise types','Speaking','Listening','Reading','Writing','Guided results','Role plays saved','Strengths','Areas to consolidate','Trainer notes','Next steps','Lesson URL'],row=[d.learner,d.lesson,d.date,d.duration_minutes,d.status,'Welcome; collect/transcribe; transmit instructions; read/analyse; timed mock','QCM; multi-select; fill; word order; interaction; listening; reading; speaking; writing',d.skills.speaking,d.skills.listening,d.skills.reading,d.skills.writing,d.guided_checks.map(c=>`${c.name}: ${c.correct}/${c.total}`).join(' | '),d.scenario_notes_saved,d.strengths,d.areas_to_consolidate,d.trainer_observations,d.next_steps,d.lesson_url];download('Francoise_LILATE_CFL_Report.csv','\ufeff'+[heads,row].map(r=>r.map(csvCell).join(';')).join('\r\n'),'text/csv;charset=utf-8')}
document.addEventListener('click',e=>{let b=e.target.closest('button');if(!b)return;let d=b.dataset;if(b.id==='accept'){$('disclaimer').classList.add('hidden');return}if(b.id==='disclaimerAgain'){$('disclaimer').classList.remove('hidden');return}if(d.page!==undefined){go(+d.page);return}if(b.id==='prev'){go(state.page-1);return}if(b.id==='next'){go(state.page+1);return}if(d.say!==undefined){speak(d.say);return}if(d.recstart!==undefined){startRecorder(d.recstart);return}if(d.recstop!==undefined){stopRecorder();return}if(d.custom==='intro'){state.results.introduction={text:$('selfintro').value};save();alert('Introduction saved in this browser.');return}if(d.choice!==undefined){let q=quizById(d.choice),container=$(d.choice+'choices');if(q.type==='single'){container.querySelectorAll('.choice').forEach(x=>x.classList.remove('chosen'));b.classList.add('chosen');judge(d.choice,+d.idx===q.answer);b.classList.add(+d.idx===q.answer?'correct':'wrong')}else{b.classList.toggle('chosen')}return}if(d.checkmulti){let q=quizById(d.checkmulti),selected=[...$(d.checkmulti+'choices').querySelectorAll('.choice.chosen')].map(x=>+x.dataset.idx).sort((a,b)=>a-b);judge(d.checkmulti,JSON.stringify(selected)===JSON.stringify(q.answer));return}if(d.checkfill){let q=quizById(d.checkfill);judge(d.checkfill,$(d.checkfill+'input').value.trim().toLowerCase().replace(/[.!?]/g,'')===q.answer.toLowerCase());return}if(d.token){let selected=$(d.token+'selected');b.parentNode===selected?$(d.token+'tokens').append(b):selected.append(b);return}if(d.checkorder){let q=quizById(d.checkorder),tokens=[...$(d.checkorder+'selected').children].map(x=>+x.dataset.key);judge(d.checkorder,JSON.stringify(tokens)===JSON.stringify(q.tokens.map((v,k)=>k)));return}if(d.resetorder){$(d.resetorder+'selected').querySelectorAll('button').forEach(x=>$(d.resetorder+'tokens').append(x));return}if(d.hint){showExtra(d.hint,`<div class="hint">💡 ${E(quizById(d.hint).hint)}</div>`);return}if(d.answer){showExtra(d.answer,`<div class="model"><strong>Suggested answer</strong>${E(answerText(quizById(d.answer)))}</div>`);return}if(d.hintscenario||d.model){let id=d.hintscenario||d.model,m=id.match(/^s(\d+)_(\d+)$/),s=parts[+m[1]].scenarios[+m[2]];$(id+'support').innerHTML=d.hintscenario?`<div class="hint">💡 ${E(s.hint)}</div>`:`<div class="model"><strong>Level A2/B1</strong>${E(s.a)}</div><div class="model"><strong>Level B1+/B2</strong>${E(s.b)}</div>`;return}if(d.saveresponse){state.results[d.saveresponse]={text:$(d.saveresponse+'response').value};save();$(d.saveresponse+'support').innerHTML='<div class="score">Response notes saved locally. Ask your trainer for feedback on your spoken answer.</div>';return}if(d.transcript){let prompt=b.closest('.prompt').querySelector('p');prompt.classList.toggle('hidden');return}if(b.id==='startMock'||b.id==='retryMock'){startMock();return}if(b.id==='submitMock'){nextMock();return}if(b.id==='endMock'){finishMock();return}if(b.id==='pauseMock'){if(state.mockRunning){stopTimer();b.textContent='Resume practice timer'}else{startTimer();b.textContent='Pause practice timer'}return}if(b.id==='copyReport'){let txt=reportText(reportData());navigator.clipboard?.writeText(txt).then(()=>$('reportFeedback').textContent='✓ Summary copied.').catch(()=>{let t=document.createElement('textarea');t.value=txt;document.body.append(t);t.select();document.execCommand('copy');t.remove();$('reportFeedback').textContent='Summary copied (fallback).'});return}if(b.id==='csvReport'){exportCSV();return}if(b.id==='jsonReport'){download('Francoise_LILATE_Report.json',JSON.stringify(reportData(),null,2),'application/json');return}if(b.id==='printReport'){window.print();return}});
document.addEventListener('change',e=>{if(e.target.id==='vocabSelect')$('vocabGrid').innerHTML=vocabHTML(state.page-1,e.target.value);if(e.target.id==='scenarioSelect'){let i=state.page-1,j=+e.target.value;state.scenario[i]=j;stopRecorder();$('scenarioArea').innerHTML=scenarioHTML(i,j);save()}});
window.addEventListener('beforeunload',()=>{stopTimer();stopRecorder()});load();render();
